import http.client
import json
import subprocess
import time

import pytest

HOST, PORT = "127.0.0.1", 8471


@pytest.fixture(scope="module", autouse=True)
def server():
    proc = subprocess.Popen(
        ["python3", "policy_server.py"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    for _ in range(50):
        try:
            conn = http.client.HTTPConnection(HOST, PORT, timeout=1)
            conn.request("GET", "/healthz")
            if conn.getresponse().read() == b"ok":
                break
        except OSError:
            time.sleep(0.1)
    else:
        proc.kill()
        raise RuntimeError("server did not become healthy")
    yield proc
    proc.terminate()
    proc.wait(timeout=5)


def post(payload=None, raw=None):
    conn = http.client.HTTPConnection(HOST, PORT, timeout=5)
    body = raw if raw is not None else json.dumps(payload)
    conn.request("POST", "/evaluate", body=body,
                 headers={"Content-Type": "application/json"})
    resp = conn.getresponse()
    data = resp.read()
    conn.close()
    return resp.status, json.loads(data) if data.startswith(b"{") else data


def get(path):
    conn = http.client.HTTPConnection(HOST, PORT, timeout=5)
    conn.request("GET", path)
    resp = conn.getresponse()
    data = resp.read()
    conn.close()
    return resp.status, data


def test_healthz():
    assert get("/healthz") == (200, b"ok")


def test_auditor_read_anything():
    status, out = post({"role": "auditor", "action": "read", "resource": "case/42"})
    assert status == 200
    assert out == {"decision": "allow", "rule": "auditor-read"}

    status, out = post({"role": "auditor", "action": "read", "resource": "person/7"})
    assert status == 200
    assert out == {"decision": "allow", "rule": "auditor-read"}


def test_clerk_read_create_case():
    status, out = post({"role": "clerk", "action": "create", "resource": "case/99"})
    assert status == 200
    assert out == {"decision": "allow", "rule": "clerk-case"}

    status, out = post({"role": "clerk", "action": "read", "resource": "case/1"})
    assert status == 200
    assert out == {"decision": "allow", "rule": "clerk-case"}


def test_judge_anything_on_case():
    status, out = post({"role": "judge", "action": "delete", "resource": "case/5"})
    assert status == 200
    assert out == {"decision": "allow", "rule": "judge-case"}

    status, out = post({"role": "judge", "action": "update", "resource": "case/x"})
    assert status == 200
    assert out == {"decision": "allow", "rule": "judge-case"}


def test_denies():
    # clerk outside case/
    _, out = post({"role": "clerk", "action": "read", "resource": "person/1"})
    assert out == {"decision": "deny", "rule": None}

    # judge outside case/
    _, out = post({"role": "judge", "action": "read", "resource": "warrant/9"})
    assert out == {"decision": "deny", "rule": None}

    # auditor non-read action
    _, out = post({"role": "auditor", "action": "delete", "resource": "case/3"})
    assert out == {"decision": "deny", "rule": None}


def test_bad_request():
    status, out = post(raw=b"{not json")
    assert status == 400
    assert out == {"error": "bad request"}

